local function _fromHex(h)
    local r = ""
    for i = 1, #h, 2 do
        r = r .. string.char(tonumber(h:sub(i, i+1), 16))
    end
    return r
end

local function _b64Decode(t)
    return (_fromHex(t):gsub('.', function(x)
        return string.char(x:byte())
    end))
end

local function _fromNumBase(t)
    local r = ""
    for p in t:gmatch("[^;]+") do
        local n1 = p:match("(%d+)_")
        if n1 then
            r = r .. string.char(tonumber(n1) // 7)
        end
    end
    return r
end

